//! Root `File Type` identification and the pipe-network families
//! (`tests/fixtures/terrio_io`, generated by its `make_fixtures.py`).
#![cfg(feature = "hdf")]

use ras_commander_fast_hdf::hdf::metadata::{MetadataValue, StoredFileType, HEC_RAS_FILE_TYPES};
use ras_commander_fast_hdf::hdf::xs_geometry::{
    OneDLineFamily, ONE_D_LINE_FAMILIES, PIPE_LINE_FAMILIES,
};
use ras_commander_fast_hdf::hdf::{NumericValues, ReadOnlyHdfSession};
use ras_commander_fast_hdf::ErrorKind;
use sha2::{Digest, Sha256};

const MB: usize = 1 << 20;

fn open(name: &str) -> ReadOnlyHdfSession {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/terrio_io");
    let manifest: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(format!("{dir}/manifest.json")).unwrap())
            .unwrap();
    let path = format!("{dir}/{name}");
    let digest = Sha256::digest(std::fs::read(&path).unwrap());
    let hex: String = digest.iter().map(|b| format!("{b:02x}")).collect();
    assert_eq!(
        manifest["fixtures"][name].as_str(),
        Some(hex.as_str()),
        "{name}: SHA256 differs from the manifest"
    );
    ReadOnlyHdfSession::open(path).unwrap()
}

#[test]
fn file_type_identifies_hec_ras_geometry_and_plan_files_only() {
    assert_eq!(HEC_RAS_FILE_TYPES, &["HEC-RAS Geometry", "HEC-RAS Results"]);
    let geometry = open("pipes.h5").hec_ras_file_type().unwrap();
    assert_eq!(geometry, StoredFileType::HecRas("HEC-RAS Geometry".into()));
    assert!(geometry.is_hec_ras());
    // Null-padded storage decodes to the same text, as h5py reads it.
    assert_eq!(
        open("results_nullpad.h5").hec_ras_file_type().unwrap(),
        StoredFileType::HecRas("HEC-RAS Results".into())
    );
    let terrain = open("terrain.h5").hec_ras_file_type().unwrap();
    assert_eq!(terrain, StoredFileType::Other("HEC Terrain".into()));
    assert!(!terrain.is_hec_ras());
    assert_eq!(
        open("no_file_type.h5").hec_ras_file_type().unwrap(),
        StoredFileType::Absent
    );
    for name in ["file_type_integer.h5", "file_type_two_strings.h5"] {
        let e = open(name).hec_ras_file_type().unwrap_err();
        assert_eq!(e.kind, ErrorKind::Unsupported, "{name}: {e:?}");
    }
}

#[test]
fn pipe_conduits_are_a_packed_line_family_outside_the_one_d_list() {
    assert_eq!(PIPE_LINE_FAMILIES, &[OneDLineFamily::PipeConduits]);
    assert!(!ONE_D_LINE_FAMILIES.contains(&OneDLineFamily::PipeConduits));
    let f = OneDLineFamily::PipeConduits;
    assert_eq!(
        (f.as_str(), f.group_path(), f.prefix()),
        ("pipe_conduits", "Geometry/Pipe Conduits", "Polyline")
    );

    let s = open("pipes.h5");
    let data = s.one_d_line_family(f, 64 * MB).unwrap();
    let data = data.value().expect("pipe conduits are supported");
    assert_eq!(data.features.len(), 2);
    assert_eq!(data.features[0].parts, vec![0..2]);
    assert_eq!(data.features[1].parts, vec![2..5]);
    assert_eq!(data.features[1].id.row, 1);
    assert_eq!(data.points.shape, vec![5, 2]);
    match &data.points.values {
        NumericValues::F64(v) => {
            assert_eq!(v, &[0.0, 0.0, 10.0, 0.0, 10.0, 0.0, 15.0, 5.0, 20.0, 5.0])
        }
        other => panic!("points: {other:?}"),
    }
    let table = &data.attributes.as_ref().expect("stored Attributes").table;
    let names: Vec<_> = table.columns.iter().map(|c| c.name.as_str()).collect();
    assert_eq!(
        names,
        [
            "Name",
            "System Name",
            "US Node",
            "DS Node",
            "Conduit Length",
            "Rise",
            "Manning's n",
            "DS Flap Gate"
        ]
    );
    assert_eq!(
        table.columns[0].value,
        MetadataValue::Strings(vec!["C1".into(), "C2".into()])
    );
    assert_eq!(
        table.columns[4].value,
        MetadataValue::Float(vec![120.5, 80.25])
    );
    // float32 widened exactly.
    assert_eq!(
        table.columns[6].value,
        MetadataValue::Float(vec![f64::from(0.013f32), f64::from(0.015f32)])
    );
    assert_eq!(table.columns[7].value, MetadataValue::Unsigned(vec![1, 0]));
}

#[test]
fn pipe_nodes_are_a_point_family() {
    let s = open("pipes.h5");
    let nodes = s.pipe_nodes(64 * MB).unwrap();
    let nodes = nodes.value().expect("pipe nodes are supported");
    assert_eq!(nodes.group, "Geometry/Pipe Nodes");
    assert_eq!(nodes.features.len(), 3);
    assert_eq!(nodes.points.shape, vec![3, 2]);
    let names: Vec<_> = nodes.names.iter().map(|n| n.value().cloned()).collect();
    assert_eq!(
        names,
        [
            Some("N1".to_string()),
            Some("N2".to_string()),
            Some("N3".to_string())
        ]
    );
    assert_eq!(
        nodes.attributes.table.columns[2].value,
        MetadataValue::Float(vec![36.0625, 35.5, 34.25])
    );
    // Absent in files without a pipe network.
    assert!(open("terrain.h5")
        .pipe_nodes(64 * MB)
        .unwrap()
        .is_unavailable());
    assert!(open("terrain.h5")
        .one_d_line_family(OneDLineFamily::PipeConduits, 64 * MB)
        .unwrap()
        .is_unavailable());
}
